    "    if result_path.exists():\n",
    "        try:\n",
    "            with open(result_path, 'r') as f:\n",
    "                existing = json.load(f)\n",
    "            if existing.get('status') == 'completed':\n",
    "                print(f'  -> COMPLETED (skipping)')\n",
    "                all_results.append(existing)\n",
    "                continue\n",
    "        except:\n",
    "            pass\n",
    "    \n",
    "    # Update manifest\n",
