    "        update_manifest(exp.name, {\n",
    "            'status': 'completed',\n",
    "            'end_time': datetime.now().isoformat(),\n",
    "            'metrics': {k: result[k] for k in ['accuracy', 'f1', 'roc_auc', 'pr_auc', 'fpr', 'fnr'] if k in result},\n",
