# CELL 15: LaTeX Table
# =============================================================================
cells.append(code([
    "# Generate LaTeX table\n",
    "def generate_latex(results, baseline_r):\n",
    "    lines = []\n",
    "    lines.append(r'\\begin{table*}[t]')\n",
    "    lines.append(r'\\centering')\n",
    "    lines.append(r'\\caption{Ablation Study Results for Hybrid Guardrail V3. Bold values indicate the best performance in each column. $\\Delta$ values show the change relative to the full baseline (Ablation 0).}')\n",
    "    lines.append(r'\\label{tab:ablation}')\n",
    "    lines.append(r'\\small')\n",
    "    lines.append(r'\\begin{tabular}{l c c c c c c c c c}')\n",
    "    lines.append(r'\\toprule')\n",
    "    lines.append(r'\\textbf{Experiment} & \\textbf{Feat.} & \\textbf{Acc.} & \\textbf{Prec.} & \\textbf{Rec.} & \\textbf{F1} & \\textbf{ROC-AUC} & \\textbf{PR-AUC} & \\textbf{FPR} & \\textbf{FNR} \\\\')\n",
    "    lines.append(r'\\midrule')\n",
    "    \n",
    "    # Find best values\n",
    "    completed = [r for r in results if r.get('status') == 'completed']\n",
    "    best = {}\n",
    "    for metric in ['accuracy', 'precision', 'recall', 'f1', 'roc_auc', 'pr_auc']:\n",
    "        vals = [(r.get(metric, 0) or 0) for r in completed]\n",
    "        best[metric] = max(vals)\n",
    "    best['fpr'] = min((r.get('fpr', 1) or 1) for r in completed)\n",
    "    best['fnr'] = min((r.get('fnr', 1) or 1) for r in completed)\n",
    "    \n",
    "    def fmt(val, metric, bold=False):\n",
    "        if val is None:\n",
    "            return 'N/A'\n",
    "        s = f'{val:.4f}'\n",
    "        if bold and abs(val - best.get(metric, 0)) < 1e-6:\n",
    "            return f'\\\\textbf{{{s}}}'\n",
    "        return s\n",
    "    \n",
    "    for r in completed:\n",
    "        name = r['name'].replace('ablation_', '').replace('_', ' ')\n",
    "        nf = r.get('total_features', 0)\n",
    "        is_baseline = (r.get('name') == 'ablation_0_full')\n",
    "        \n",
    "        # Delta markers\n",
    "        delta_str = ''\n",
    "        if not is_baseline and baseline_r:\n",
    "            d_f1 = r.get('f1', 0) - baseline_r.get('f1', 0)\n",
    "            delta_str = f' ($\\Delta${d_f1:+.3f})' if abs(d_f1) > 1e-6 else ''\n",
    "        \n",
    "        row = (\n",
    "            f'{name}{delta_str} & {nf} '\n",
    "            f'& {fmt(r.get(\"accuracy\"), \"accuracy\", not is_baseline)} '\n",
    "            f'& {fmt(r.get(\"precision\"), \"precision\", not is_baseline)} '\n",
    "            f'& {fmt(r.get(\"recall\"), \"recall\", not is_baseline)} '\n",
    "            f'& {fmt(r.get(\"f1\"), \"f1\", not is_baseline)} '\n",
    "            f'& {fmt(r.get(\"roc_auc\"), \"roc_auc\", not is_baseline)} '\n",
    "            f'& {fmt(r.get(\"pr_auc\"), \"pr_auc\", not is_baseline)} '\n",
    "            f'& {fmt(r.get(\"fpr\"), \"fpr\", not is_baseline)} '\n",
    "            f'& {fmt(r.get(\"fnr\"), \"fnr\", not is_baseline)} '\n",
    "            f'\\\\\\\\'\n",
    "        )\n",
    "        lines.append(row)\n",
    "    \n",
    "    lines.append(r'\\bottomrule')\n",
    "    lines.append(r'\\end{tabular}')\n",
    "    lines.append(r'\\end{table*}')\n",
    "    return '\\n'.join(lines)\n",
    "\n",
    "latex = generate_latex(all_results, baseline)\n",
    "\n",
    "# Save\n",
    "tex_path = TABLE_DIR / 'ablation_results.tex'\n",
    "with open(tex_path, 'w') as f:\n",
    "    f.write(latex)\n",
    "print(f'Saved: {tex_path}')\n",
    "print('\\nLaTeX table:')\n",
    "print(latex)"
]))

